from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def R_beta_of(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    m = L.max()
    z = beta * (L - m)
    lse = m + np.log(np.sum(np.exp(z))) / beta
    if lse <= 0:
        return -1.0
    return sq / (s * s * lse)


def grad_R_beta(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    m = L.max()
    z = beta * (L - m)
    ez = np.exp(z)
    sez = ez.sum()
    w = ez / sez
    lse = m + np.log(sez) / beta
    dC_dh = np.zeros(N)
    nz = np.where(w > 1e-12)[0]
    for kL in nz:
        wk = w[kL]
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * wk * h[k - idx]
    C = lse
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs_beta(h, beta, deadline, maxiter=4000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h
    try:
        res = minimize(
            fun=lambda x: -R_beta_of(x, beta),
            jac=lambda x: -grad_R_beta(x, beta),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        return np.maximum(0.0, res.x)
    except Exception:
        return h


def coord_sweep(h, deadline, rng=None, fine=False):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    mults = (0.0, 0.5, 0.8, 0.9, 0.95, 1.05, 1.1, 1.25, 1.6, 2.0)
    if fine:
        mults = (0.0, 0.9, 0.95, 0.98, 1.02, 1.05, 1.1, 1.25)
    adds = (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5)
    if fine:
        adds = (-0.05, -0.01, 0.01, 0.05)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in mults:
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        for add in adds:
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(
                neg_R_pair, x0, method='Nelder-Mead',
                bounds=[(0.0, None), (0.0, None)],
                options={'maxiter': 30, 'xatol': 1e-6, 'fatol': 1e-12},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    x_old = np.arange(N)
    x_new = np.linspace(0, N - 1, N2)
    return np.interp(x_new, x_old, h)


def refine(h0, N2, deadline, rng, betas=(20, 50, 100, 200, 400, 800, 1600)):
    h = upsample(h0, N2)
    best = h.copy()
    best_r = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        h = polish_lbfgs_beta(h, beta, deadline)
        h, r = coord_sweep(h, deadline, rng=rng, fine=True)
        rex = R_of(h)
        if rex > best_r:
            best, best_r = h.copy(), rex
    return best, best_r


def smooth_perturb(h, rng, eps=None):
    N = len(h)
    x = np.linspace(0.0, 1.0, N)
    if eps is None:
        eps = rng.uniform(0.005, 0.04)
    p = np.ones(N)
    for _ in range(3):
        f = rng.uniform(0.5, 6.0)
        a = rng.standard_normal()
        phi = rng.uniform(0.0, 2.0 * np.pi)
        p += eps * a * np.cos(np.pi * f * x + phi)
    p = np.clip(p, 0.5, 1.5)
    return np.maximum(0.0, h * p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240711)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Pairwise sweeps on start (cheap, effective for local refinement)
    if time.process_time() < hard_deadline:
        h = best.copy()
        sweep = 0
        while time.process_time() < hard_deadline:
            sweep += 1
            h, r = pair_sweep(h, hard_deadline, rng)
            if r > best_r:
                best, best_r = h.copy(), r
                print(f"pair sweep {sweep}: R={best_r:.9f}")
            else:
                break

    # Beta-smoothed refinement at current N and slightly larger Ns
    it = 0
    while time.process_time() < hard_deadline:
        it += 1
        # Alternate: refine at current N, and try a slightly larger N
        if it % 3 == 1:
            N_try = len(best)
        elif it % 3 == 2:
            N_try = min(50000, len(best) + int(rng.integers(10, 80)))
        else:
            N_try = max(64, len(best) - int(rng.integers(5, 40)))

        seed = upsample(best, N_try)
        if it % 2 == 0:
            seed = smooth_perturb(seed, rng)
        h, r = refine(seed, N_try, hard_deadline, rng)
        if time.process_time() >= hard_deadline:
            if r > best_r:
                best, best_r = h, r
            break
        if r > best_r:
            best, best_r = h.copy(), r
            print(f"refine {it}: R={best_r:.9f} N={len(best)}")

    # Final coord sweep
    if time.process_time() < hard_deadline:
        h, r = coord_sweep(best.copy(), hard_deadline, rng=rng, fine=True)
        if r > best_r:
            best, best_r = h, r
        print(f"final coord R={best_r:.9f} N={len(best)}")

    print("final R =", best_r, "N =", len(best))
    return np.asarray(best, dtype=float)

