def block_sweep(h, deadline, rng, B):
    """Sweep blocks of B consecutive indices in random order, Nelder-Mead on exact R."""
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - B + 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = h[i:i + B].copy()

        def neg_R_block(x):
            h[i:i + B] = x
            return -R_of(h)

        try:
            res = minimize(
                neg_R_block, x0, method='Nelder-Mead',
                bounds=[(0.0, None)] * B,
                options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Symmetrization: project onto symmetric subspace if it does not hurt.
    if len(best) >= 2:
        h_sym = 0.5 * (best + best[::-1])
        r_sym = R_of(h_sym)
        if r_sym >= best_r:
            best = h_sym
            best_r = r_sym
            print(f"symmetrized: R={best_r:.9f}")

    # Pairwise polishing sweeps
    if time.process_time() < hard_deadline:
        h = best.copy()
        sweep = 0
        while time.process_time() < hard_deadline:
            sweep += 1
            h, r = pair_sweep(h, hard_deadline, rng)
            if r > best_r:
                best, best_r = h.copy(), r
                print(f"pair sweep {sweep}: R={best_r:.9f}")
            else:
                break

    # Block sweeps with B=3 then B=4, repeated until no improvement
    if time.process_time() < hard_deadline:
        h = best.copy()
        pass_no = 0
        while time.process_time() < hard_deadline:
            pass_no += 1
            improved = False
            for B in (3, 4):
                if time.process_time() >= hard_deadline:
                    break
                h, r = block_sweep(h, hard_deadline, rng, B)
                if r > best_r + 1e-12:
                    best, best_r = h.copy(), r
                    improved = True
                    print(f"block pass {pass_no} B={B}: R={best_r:.9f}")
            if not improved:
                break

    print("final R =", best_r, "N =", len(best))
    return best

