    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def R_beta_of(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    m = L.max()
    z = beta * (L - m)
    lse = m + np.log(np.sum(np.exp(z))) / beta
    if lse <= 0:
        return -1.0
    return sq / (s * s * lse)


def grad_R_beta(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    m = L.max()
    z = beta * (L - m)
    ez = np.exp(z)
    sez = ez.sum()
    w = ez / sez
    lse = m + np.log(sez) / beta
    dC_dh = np.zeros(N)
    for kL in range(len(L)):
        wk = w[kL]
        if wk < 1e-12:
            continue
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * wk * h[k - idx]
    C = lse
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs_beta(h, beta, deadline, maxiter=3000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h
    try:
        res = minimize(
            fun=lambda x: -R_beta_of(x, beta),
            jac=lambda x: -grad_R_beta(x, beta),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        cand = np.maximum(0.0, res.x)
        return cand
    except Exception:
        return h


def coord_sweep(h, deadline, rng=None, fine=False):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    mults = (0.0, 0.5, 0.8, 0.9, 0.95, 1.05, 1.1, 1.25, 1.6, 2.0)
    if fine:
        mults = (0.0, 0.9, 0.95, 0.98, 1.02, 1.05, 1.1, 1.25)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in mults:
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        adds = (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5)
        if fine:
            adds = (-0.05, -0.01, 0.01, 0.05)
        for add in adds:
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(
                neg_R_pair, x0, method='Nelder-Mead',
                bounds=[(0.0, None), (0.0, None)],
                options={'maxiter': 30, 'xatol': 1e-6, 'fatol': 1e-12},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def block_sweep(h, deadline, rng, B):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - B + 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = h[i:i + B].copy()

        def neg_R_block(x):
            h[i:i + B] = x
            return -R_of(h)

        try:
            res = minimize(
                neg_R_block, x0, method='Nelder-Mead',
                bounds=[(0.0, None)] * B,
                options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    x_old = np.arange(N)
    x_new = np.linspace(0, N - 1, N2)
    return np.interp(x_new, x_old, h)


def downsample_avg(h, N2):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N2 >= N:
        return h.copy()
    # pad to multiple of N2 if needed by repeating last value
    pad = (-N) % N2
    if pad:
        h = np.concatenate([h, np.full(pad, h[-1])])
    return h.reshape(-1, N2).mean(axis=0)


def refine(h0, N2, deadline, rng, betas=(20, 50, 100, 200, 400, 800)):
    h = upsample(h0, N2)
    best = h.copy()
    best_r = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        h = polish_lbfgs_beta(h, beta, deadline)
        h, r = coord_sweep(h, deadline, rng=rng, fine=True)
        rex = R_of(h)
        if rex > best_r:
            best, best_r = h.copy(), rex
    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.92
    coarse_deadline = t0 + budget_seconds * 0.40
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    N_full = len(best)

    # ---- Coarse phase: downsample to ~N/2, optimize exact R there ----
    if N_full >= 4:
        N_coarse = max(2, (N_full + 1) // 2)
        hc = downsample_avg(best, N_coarse)
        rc = R_of(hc)
        print(f"coarse N={N_coarse} R={rc:.9f}")

        # pair sweeps at coarse level
        sweep = 0
        while time.process_time() < coarse_deadline:
            sweep += 1
            hc, r = pair_sweep(hc, coarse_deadline, rng)
            if r > rc + 1e-14:
                rc = r
                print(f"coarse pair sweep {sweep}: R={rc:.9f}")
            else:
                break

        # block sweeps B=3,4 at coarse level
        pass_no = 0
        while time.process_time() < coarse_deadline:
            pass_no += 1
            improved = False
            for B in (3, 4):
                if time.process_time() >= coarse_deadline:
                    break
                hc, r = block_sweep(hc, coarse_deadline, rng, B)
                if r > rc + 1e-14:
                    rc = r
                    improved = True
                    print(f"coarse block pass {pass_no} B={B}: R={rc:.9f}")
            if not improved:
                break

        # Upsample coarse result back to full resolution
        h_up = upsample(hc, N_full)
        r_up = R_of(h_up)
        print(f"upsampled R={r_up:.9f}")
        if r_up > best_r:
            best, best_r = h_up.copy(), r_up
            print(f"accepted coarse-to-fine: R={best_r:.9f}")

    # ---- Fine phase: pair_sweep + block_sweep B=3,4 + fine coord_sweep ----
    if time.process_time() < hard_deadline:
        h = best.copy()
        sweep = 0
        while time.process_time() < hard_deadline:
            sweep += 1
            h, r = pair_sweep(h, hard_deadline, rng)
            if r > best_r + 1e-14:
                best, best_r = h.copy(), r
                print(f"pair sweep {sweep}: R={best_r:.9f}")
            else:
                break

    if time.process_time() < hard_deadline:
        h = best.copy()
        pass_no = 0
        while time.process_time() < hard_deadline:
            pass_no += 1
            improved = False
            for B in (3, 4):
                if time.process_time() >= hard_deadline:
                    break
                h, r = block_sweep(h, hard_deadline, rng, B)
                if r > best_r + 1e-12:
                    best, best_r = h.copy(), r
                    improved = True
                    print(f"block pass {pass_no} B={B}: R={best_r:.9f}")
            if not improved:
                break

    if time.process_time() < hard_deadline:
        h, r = coord_sweep(best.copy(), hard_deadline, rng=rng, fine=True)
        if r > best_r:
            best, best_r = h, r
        print(f"final coord R={best_r:.9f} N={len(best)}")

    print("final R =", best_r, "N =", len(best))
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _R_and_grad(h):
    """Return R and its gradient w.r.t. h, using the exact max (subgradient)."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    m = L.max()
    B = s * s
    if m <= 0:
        return -1.0, np.zeros_like(h)
    # subgradient of max: one-hot at argmax of L (knot index -> h index)
    k = int(np.argmax(L))
    # L index k corresponds to convolution index k-1 -> h indices i+j=k-1
    dC_dh = np.zeros(N)
    if 1 <= k <= 2 * N - 1:
        c = k - 1
        for i in range(N):
            j = c - i
            if 0 <= j < N:
                dC_dh[i] += h[j]
        dC_dh *= 2.0
    dB_dh = 2.0 * s
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * m) - A * dC_dh / (B * m * m)
    return A / (B * m), dR_dh


def polish_lbfgs(h, deadline, maxiter=2000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h
    try:
        res = minimize(
            fun=lambda x: -_R_and_grad(x)[0],
            jac=lambda x: -_R_and_grad(x)[1],
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-18, 'gtol': 1e-14, 'maxls': 80},
        )
        return np.maximum(0.0, res.x)
    except Exception:
        return h


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(
                neg_R_pair, x0, method='Nelder-Mead',
                bounds=[(0.0, None), (0.0, None)],
                options={'maxiter': 40, 'xatol': 1e-8, 'fatol': 1e-14},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def block_sweep(h, deadline, rng, B):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - B + 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = h[i:i + B].copy()

        def neg_R_block(x):
            h[i:i + B] = x
            return -R_of(h)

        try:
            res = minimize(
                neg_R_block, x0, method='Nelder-Mead',
                bounds=[(0.0, None)] * B,
                options={'maxiter': 80, 'xatol': 1e-8, 'fatol': 1e-14},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Symmetrize if it does not hurt.
    if len(best) >= 2:
        h_sym = 0.5 * (best + best[::-1])
        r_sym = R_of(h_sym)
        if r_sym >= best_r:
            best = h_sym
            best_r = r_sym
            print(f"symmetrized: R={best_r:.9f}")

    # Phase 1: exact-max LBFGS (fast, uses analytic gradient).
    h = best.copy()
    for _ in range(3):
        if time.process_time() >= hard_deadline:
            break
        h2 = polish_lbfgs(h, hard_deadline, maxiter=1500)
        r2 = R_of(h2)
        if r2 > best_r:
            best, best_r = h2.copy(), r2
            print(f"lbfgs: R={best_r:.9f}")
        h = best.copy()

    # Phase 2: pairwise then block sweeps.
    sweep = 0
    while time.process_time() < hard_deadline:
        sweep += 1
        h, r = pair_sweep(best.copy(), hard_deadline, rng)
        if r > best_r + 1e-13:
            best, best_r = h.copy(), r
            print(f"pair sweep {sweep}: R={best_r:.9f}")
        else:
            break

    pass_no = 0
    while time.process_time() < hard_deadline:
        pass_no += 1
        improved = False
        for B in (3, 4, 5):
            if time.process_time() >= hard_deadline:
                break
            h, r = block_sweep(best.copy(), hard_deadline, rng, B)
            if r > best_r + 1e-13:
                best, best_r = h.copy(), r
                improved = True
                print(f"block pass {pass_no} B={B}: R={best_r:.9f}")
        if not improved:
            break

    # Phase 3: final LBFGS + pair polish.
    while time.process_time() < hard_deadline:
        h2 = polish_lbfgs(best.copy(), hard_deadline, maxiter=1000)
        r2 = R_of(h2)
        if r2 > best_r + 1e-13:
            best, best_r = h2.copy(), r2
            print(f"final lbfgs: R={best_r:.9f}")
        else:
            break
        h, r = pair_sweep(best.copy(), hard_deadline, rng)
        if r > best_r + 1e-13:
            best, best_r = h.copy(), r
            print(f"final pair: R={best_r:.9f}")
        else:
            break

    best = np.maximum(0.0, best)
    print("final R =", best_r, "N =", len(best))
    return best

