        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def block_sweep(h, deadline, rng, B):
    """Sweep blocks of B consecutive indices in random order, Nelder-Mead on exact R."""
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
