                options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    x_old = np.arange(N)
    x_new = np.linspace(0, N - 1, N2)
