def refine(h0, N2, deadline, rng, betas=(20, 50, 100, 200, 400, 800)):
    h = upsample(h0, N2)
    best = h.copy()
    best_r = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        h = polish_lbfgs_beta(h, beta, deadline)
        h, r = coord_sweep(h, deadline, rng=rng, fine=True)
        rex = R_of(h)
        if rex > best_r:
            best, best_r = h.copy(), rex
    return best, best_r


def downsample_avg(h, M):
    h = np.asarray(h, dtype=float)
    N = len(h)
    x_new = np.linspace(0, N, M + 1)
    c = np.zeros(M)
    for i in range(M):
        lo = int(np.floor(x_new[i]))
        hi = int(np.ceil(x_new[i + 1]))
        lo = max(0, min(N - 1, lo))
        hi = max(lo + 1, min(N, hi))
        c[i] = h[lo:hi].mean()
    return c


def spline_opt(c, N, deadline, maxiter=400):
    t = np.linspace(0.0, 1.0, N)
    tc = np.linspace(0.0, 1.0, len(c))

    def neg_R(x):
        h = np.interp(t, tc, x)
        return -R_of(h)

    try:
        res = minimize(
            neg_R, np.maximum(0.0, c), method='L-BFGS-B',
            bounds=[(0.0, None)] * len(c),
            options={'maxiter': maxiter},
        )
        return np.maximum(0.0, res.x)
    except Exception:
        return np.asarray(c, dtype=float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    N = 649
    M = 24
    t = np.linspace(0.0, 1.0, N)
    tc = np.linspace(0.0, 1.0, M)

    # Multi-start spline optimization
    starts = []
    if start is not None and len(start) >= 2:
        starts.append(downsample_avg(start, M))
    starts.append(np.ones(M))
    starts.append((1.0 - (2.0 * t - 1.0) ** 2) ** 2 if False else
                  np.interp(tc, t, (1.0 - (2.0 * t - 1.0) ** 2) ** 2))

    best_c = None
    best_c_r = -1.0
    for si, c0 in enumerate(starts):
        if time.process_time() >= hard_deadline:
            break
        c = spline_opt(c0, N, hard_deadline)
        h = np.interp(t, tc, c)
        r = R_of(h)
        print(f"spline start {si}: R={r:.9f}")
        if r > best_c_r:
            best_c_r = r
            best_c = c

    if best_c is not None:
        h_spline = np.interp(t, tc, best_c)
        r_spline = R_of(h_spline)
        if r_spline > best_r:
            best, best_r = h_spline, r_spline
            print(f"spline improved: R={best_r:.9f}")

    # Pairwise polishing sweeps
    if time.process_time() < hard_deadline:
        h = best.copy()
        sweep = 0
        while time.process_time() < hard_deadline:
            sweep += 1
            h, r = pair_sweep(h, hard_deadline, rng)
            if r > best_r:
                best, best_r = h.copy(), r
                print(f"pair sweep {sweep}: R={best_r:.9f}")
            else:
                break

    # Block sweeps with B=3 then B=4
    if time.process_time() < hard_deadline:
        h = best.copy()
        pass_no = 0
        while time.process_time() < hard_deadline:
            pass_no += 1
            improved = False
            for B in (3, 4):
                if time.process_time() >= hard_deadline:
                    break
                h, r = block_sweep(h, hard_deadline, rng, B)
                if r > best_r + 1e-12:
                    best, best_r = h.copy(), r
                    improved = True
                    print(f"block pass {pass_no} B={B}: R={best_r:.9f}")
            if not improved:
                break

    # Final fine single-coordinate sweep
    if time.process_time() < hard_deadline:
        h, r = coord_sweep(best.copy(), hard_deadline, rng=rng, fine=True)
        if r > best_r:
            best, best_r = h, r
        print(f"final coord R={best_r:.9f} N={len(best)}")

    print("final R =", best_r, "N =", len(best))
    return best

