def symmetrize(h):
    h = np.asarray(h, dtype=float)
    return 0.5 * (h + h[::-1])


def mirror_half(half, N):
    # half has length ceil(N/2); build symmetric full array of length N
    m = len(half)
    full = np.empty(N, dtype=float)
    full[:m] = half
    full[N - m:] = half[::-1]
    return full


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        base = np.ones(64)

    N = len(base)
    # Symmetrize the start
    sym = symmetrize(base)
    best = sym.copy()
    best_r = R_of(best)
    base_r = R_of(base)
    print(f"start R = {base_r:.9f}  sym R = {best_r:.9f}  N = {N}")

    m = (N + 1) // 2  # ceil(N/2)

    def half_to_full(half):
        return mirror_half(half, N)

    def R_half(half):
        return R_of(half_to_full(half))

    # Work on the half array
    half = best[:m].copy()
    half_r = R_half(half)

    # Soft-max L-BFGS on the half array, scoring on the full symmetric array
    def polish_half_lbfgs(half, beta, deadline, maxiter=800):
        if time.process_time() >= deadline:
            return half
        try:
            res = minimize(
                fun=lambda x: -R_half(x),
                jac=lambda x: -grad_R_beta(half_to_full(x), beta)[:m],
                x0=half,
                method='L-BFGS-B',
                bounds=[(0.0, None)] * len(half),
                options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
            )
            return np.maximum(0.0, res.x)
        except Exception:
            return half

    for beta in (200, 500, 1200, 3000):
        if time.process_time() >= hard_deadline:
            break
        cand = polish_half_lbfgs(half, beta, hard_deadline)
        r_cand = R_half(cand)
        if r_cand > half_r:
            half, half_r = cand, r_cand
            full = half_to_full(half)
            if half_r > best_r:
                best, best_r = full, half_r
            print(f"half lbfgs beta={beta}: R={half_r:.9f}")

    # Pair sweep on the half array
    if time.process_time() < hard_deadline:
        hh = half.copy()
        cur = R_half(hh)
        order = np.arange(len(hh) - 1)
        rng.shuffle(order)
        for i in order:
            if time.process_time() >= hard_deadline:
                break
            x0 = np.array([hh[i], hh[i + 1]], dtype=float)

            def neg_R_pair_half(x):
                hh[i] = x[0]
                hh[i + 1] = x[1]
                return -R_half(hh)

            try:
                res = minimize(
                    neg_R_pair_half, x0, method='Nelder-Mead',
                    bounds=[(0.0, None), (0.0, None)],
                    options={'maxiter': 30, 'xatol': 1e-6, 'fatol': 1e-12},
                )
                xb = np.maximum(0.0, res.x)
            except Exception:
                xb = x0
            hh[i] = xb[0]
            hh[i + 1] = xb[1]
            r = R_half(hh)
            if r > cur:
                cur = r
            else:
                hh[i] = x0[0]
                hh[i + 1] = x0[1]
        if cur > half_r:
            half, half_r = hh, cur
            full = half_to_full(half)
            if half_r > best_r:
                best, best_r = full, half_r
            print(f"half pair sweep: R={half_r:.9f}")

    # Block sweeps B=3,4 on the half array
    for B in (3, 4):
        if time.process_time() >= hard_deadline:
            break
        if len(half) < B:
            continue
        hh = half.copy()
        cur = R_half(hh)
        order = np.arange(len(hh) - B + 1)
        rng.shuffle(order)
        for i in order:
            if time.process_time() >= hard_deadline:
                break
            x0 = hh[i:i + B].copy()

            def neg_R_block_half(x):
                hh[i:i + B] = x
                return -R_half(hh)

            try:
                res = minimize(
                    neg_R_block_half, x0, method='Nelder-Mead',
                    bounds=[(0.0, None)] * B,
                    options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13},
                )
                xb = np.maximum(0.0, res.x)
            except Exception:
                xb = x0
            hh[i:i + B] = xb
            r = R_half(hh)
            if r > cur:
                cur = r
            else:
                hh[i:i + B] = x0
        if cur > half_r:
            half, half_r = hh, cur
            full = half_to_full(half)
            if half_r > best_r:
                best, best_r = full, half_r
            print(f"half block B={B}: R={half_r:.9f}")

    # Final: compare symmetrized base with best symmetric result
    if best_r >= base_r:
        result = best
    else:
        result = base
    print("final R =", R_of(result), "N =", len(result))
    return result

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _dA_dL(L):
    return (2.0 * L
            + np.concatenate(([0.0], L[:-1]))
            + np.concatenate((L[1:], [0.0]))) / 3.0


def R_beta_of(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    m = L.max()
    z = beta * (L - m)
    lse = m + np.log(np.sum(np.exp(z))) / beta
    if lse <= 0:
        return -1.0
    return sq / (s * s * lse)


def grad_R_beta(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = _dA_dL(L)
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    m = L.max()
    z = beta * (L - m)
    ez = np.exp(z)
    sez = ez.sum()
    w = ez / sez
    lse = m + np.log(sez) / beta
    dC_dh = np.zeros(N)
    for kL in range(len(L)):
        wk = w[kL]
        if wk < 1e-12:
            continue
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * wk * h[k - idx]
    C = lse
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs_beta(h, beta, deadline, maxiter=800):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h
    try:
        res = minimize(
            fun=lambda x: -R_beta_of(x, beta),
            jac=lambda x: -grad_R_beta(x, beta),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        return np.maximum(0.0, res.x)
    except Exception:
        return h


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(
                neg_R_pair, x0, method='Nelder-Mead',
                bounds=[(0.0, None), (0.0, None)],
                options={'maxiter': 30, 'xatol': 1e-6, 'fatol': 1e-12},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def block_sweep(h, deadline, rng, B):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - B + 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = h[i:i + B].copy()

        def neg_R_block(x):
            h[i:i + B] = x
            return -R_of(h)

        try:
            res = minimize(
                neg_R_block, x0, method='Nelder-Mead',
                bounds=[(0.0, None)] * B,
                options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    x_old = np.arange(N)
    x_new = np.linspace(0, N - 1, N2)
    return np.interp(x_new, x_old, h)


def downsample_avg(h, N2):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N2 >= N:
        return h.copy()
    pad = (-N) % N2
    if pad:
        h = np.concatenate([h, np.full(pad, h[-1])])
    return h.reshape(-1, N2).mean(axis=0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base_r = R_of(base)
        print("start R =", base_r, "N =", len(base))
    else:
        base = np.ones(64)
        base_r = R_of(base)

    N0 = len(base)
    best = base.copy()
    best_r = base_r

    # Finer resolutions to try
    finer = sorted(set([2 * N0, 3 * N0]))
    finer = [n for n in finer if n <= 50000]

    # Allocate budget: each finer trial gets a fraction
    n_trials = len(finer) + 1  # +1 for the downsample re-polish
    per_trial = budget_seconds * 0.85 / max(1, n_trials)

    best_fine = None
    best_fine_r = -1.0

    for Nc in finer:
        if time.process_time() >= hard_deadline:
            break
        sub_deadline = min(hard_deadline, time.process_time() + per_trial)
        hc = upsample(base, Nc)
        rc = R_of(hc)
        print(f"trial Nc={Nc}: upsampled R={rc:.9f}")

        for beta in (500, 1500, 4000, 10000):
            if time.process_time() >= sub_deadline:
                break
            cand = polish_lbfgs_beta(hc, beta, sub_deadline, maxiter=800)
            r_cand = R_of(cand)
            if r_cand > rc:
                hc, rc = cand, r_cand
                print(f"  Nc={Nc} lbfgs beta={beta}: R={rc:.9f}")

        for _ in range(3):
            if time.process_time() >= sub_deadline:
                break
            hc, rc = pair_sweep(hc, sub_deadline, rng)
            print(f"  Nc={Nc} pair: R={rc:.9f}")

        for B in (3, 4, 6):
            if time.process_time() >= sub_deadline:
                break
            hc, rc = block_sweep(hc, sub_deadline, rng, B)
            print(f"  Nc={Nc} block B={B}: R={rc:.9f}")

        if rc > best_fine_r:
            best_fine, best_fine_r = hc.copy(), rc
        if rc > best_r:
            best, best_r = hc.copy(), rc
            print(f"trial Nc={Nc}: R={rc:.9f} (new best)")

    # Downsample best finer result back to N0 and re-polish once
    if best_fine is not None and time.process_time() < hard_deadline:
        sub_deadline = min(hard_deadline, time.process_time() + per_trial)
        hd = downsample_avg(best_fine, N0)
        rd = R_of(hd)
        print(f"downsample to {N0}: R={rd:.9f}")
        for beta in (1500, 4000, 10000):
            if time.process_time() >= sub_deadline:
                break
            cand = polish_lbfgs_beta(hd, beta, sub_deadline, maxiter=800)
            r_cand = R_of(cand)
            if r_cand > rd:
                hd, rd = cand, r_cand
                print(f"  down lbfgs beta={beta}: R={rd:.9f}")
        if time.process_time() < sub_deadline:
            hd, rd = pair_sweep(hd, sub_deadline, rng)
            print(f"  down pair: R={rd:.9f}")
        if rd > best_r:
            best, best_r = hd.copy(), rd
            print(f"downsample re-polish: R={rd:.9f} (new best)")

    # Final quick polish at N0 if time remains
    if time.process_time() < hard_deadline:
        h = best.copy()
        for beta in (4000, 10000):
            if time.process_time() >= hard_deadline:
                break
            cand = polish_lbfgs_beta(h, beta, hard_deadline, maxiter=600)
            r_cand = R_of(cand)
            if r_cand > best_r:
                h, best_r = cand, r_cand
                print(f"final lbfgs beta={beta}: R={best_r:.9f}")
        best = h

    print("final R =", best_r, "N =", len(best))
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _R_and_grad(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    m = L.max()
    B = s * s
    if m <= 0:
        return -1.0, np.zeros_like(h)
    k = int(np.argmax(L))
    dC_dh = np.zeros(N)
    if 1 <= k <= 2 * N - 1:
        c = k - 1
        lo = max(0, c - N + 1)
        hi = min(N - 1, c)
        idx = np.arange(lo, hi + 1)
        dC_dh[idx] = 2.0 * h[c - idx]
    dB_dh = 2.0 * s
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * m) - A * dC_dh / (B * m * m)
    return A / (B * m), dR_dh


def polish_lbfgs(h, deadline, maxiter=3000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h
    try:
        res = minimize(
            fun=lambda x: -_R_and_grad(x)[0],
            jac=lambda x: -_R_and_grad(x)[1],
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-18, 'gtol': 1e-14, 'maxls': 80},
        )
        return np.maximum(0.0, res.x)
    except Exception:
        return h


def coord_sweep(h, deadline, rng=None, fine=False):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    mults = (0.0, 0.5, 0.8, 0.9, 0.95, 1.05, 1.1, 1.25, 1.6, 2.0)
    if fine:
        mults = (0.0, 0.9, 0.95, 0.98, 1.02, 1.05, 1.1, 1.25)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in mults:
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        adds = (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5)
        if fine:
            adds = (-0.05, -0.01, 0.01, 0.05)
        for add in adds:
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(
                neg_R_pair, x0, method='Nelder-Mead',
                bounds=[(0.0, None), (0.0, None)],
                options={'maxiter': 50, 'xatol': 1e-9, 'fatol': 1e-15},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    x_old = np.arange(N)
    x_new = np.linspace(0, N - 1, N2)
    return np.interp(x_new, x_old, h)


def symmetrize(h):
    return 0.5 * (h + h[::-1])


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Symmetrize (optimum is symmetric)
    if len(best) >= 2:
        h_sym = symmetrize(best)
        r_sym = R_of(h_sym)
        if r_sym >= best_r - 1e-9:
            best = h_sym
            best_r = max(best_r, r_sym)

    # Phase 1: upsample and re-optimize at higher resolution
    N_full = len(best)
    candidates = []
    if N_full < 4000:
        for mult in (1.5, 2.0, 3.0, 4.0):
            N2 = int(round(N_full * mult))
            if N2 <= 50000 and N2 > N_full:
                candidates.append(N2)
    # Always try the original N too, plus a couple
    candidates = [N_full] + candidates

    for N2 in candidates:
        if time.process_time() >= hard_deadline:
            break
        if N2 == N_full:
            seed = best.copy()
        else:
            seed = upsample(best, N2)
            seed = symmetrize(seed)
        seed = np.maximum(0.0, seed)
        if seed.sum() <= 0:
            continue
        r = R_of(seed)
        if r < best_r - 0.05 and N2 != N_full:
            # too much degradation from upsampling, skip
            continue

        # allocate time proportional to level
        frac = 0.4 if N2 == N_full else 0.6 / max(1, len(candidates) - 1)
        level_deadline = min(hard_deadline,
                             time.process_time() + (hard_deadline - time.process_time()) * frac)

        h = seed
        r = R_of(h)
        for it in range(8):
            if time.process_time() >= level_deadline:
                break
            h2 = polish_lbfgs(h, level_deadline)
            r2 = R_of(h2)
            if r2 > r + 1e-12:
                h, r = h2, r2
            else:
                break
            if time.process_time() >= level_deadline:
                break
            h2, r2 = coord_sweep(h, level_deadline, rng, fine=(it > 2))
            if r2 > r + 1e-12:
                h, r = h2, r2
            else:
                break

        # symmetrize again and polish
        if time.process_time() < level_deadline:
            hs = symmetrize(h)
            rs = R_of(hs)
            if rs > r:
                h, r = hs, rs
            h2 = polish_lbfgs(h, level_deadline)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2

        print(f"level N={N2} R={r:.9f}")
        if r > best_r + 1e-12:
            best_r = r
            best = h.copy()

    # Phase 2: fine pair/coord sweeps on the best
    while time.process_time() < hard_deadline:
        improved = False
        h2, r2 = pair_sweep(best, hard_deadline, rng)
        if r2 > best_r + 1e-12:
            best, best_r = h2, r2
            improved = True
        if time.process_time() >= hard_deadline:
            break
        h2, r2 = coord_sweep(best, hard_deadline, rng, fine=True)
        if r2 > best_r + 1e-12:
            best, best_r = h2, r2
            improved = True
        if time.process_time() >= hard_deadline:
            break
        h2 = polish_lbfgs(best, hard_deadline)
        r2 = R_of(h2)
        if r2 > best_r + 1e-12:
            best, best_r = h2, r2
            improved = True
        if not improved:
            break

    best = np.maximum(0.0, best)
    best_r = R_of(best)
    print("final R =", best_r, "N =", len(best))
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
