import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _dA_dL(L):
    return (2.0 * L
            + np.concatenate(([0.0], L[:-1]))
            + np.concatenate((L[1:], [0.0]))) / 3.0


def grad_R_exact(h, active_tol=1e-6):
    """Exact dR/dh with a uniform subgradient over the active (near-max) knots."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = _dA_dL(L)
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    m = L.max()
    active = np.where(L >= m * (1.0 - active_tol))[0]
    dC_dh = np.zeros(N)
    cnt = 0
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx]
            cnt += 1
    if cnt > 0:
        dC_dh /= cnt
    C = m
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def active_set_ascent(h, deadline, max_iter=100000):
    h = np.asarray(h, dtype=float).copy()
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, R_of(h)
    h /= s
    cur_r = R_of(h)
    step = 1e-3
    it = 0
    while time.process_time() < deadline and it < max_iter:
        it += 1
        g = grad_R_exact(h)
        gn = np.linalg.norm(g)
        if gn <= 0:
            break
        d = g / gn
        improved = False
        for _ in range(40):
            hc = h + step * d
            hc = np.maximum(hc, 0.0)
            sc = hc.sum()
            if sc <= 0:
                step *= 0.5
                continue
            hc /= sc
            rc = R_of(hc)
            if rc > cur_r:
                h, cur_r = hc, rc
                step *= 1.5
                improved = True
                break
            step *= 0.5
        if not improved:
            if step < 1e-12:
                break
        if time.process_time() >= deadline:
            break
    return h, cur_r


def full_lbfgs(h, deadline):
    """L-BFGS-B with exact gradient, exploiting curvature near the optimum."""
    h = np.asarray(h, dtype=float).copy()
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, R_of(h)
    h /= s
    cur_r = R_of(h)
    if time.process_time() >= deadline:
        return h, cur_r

    def neg_R(x):
        return -R_of(x)

    def neg_grad(x):
        return -grad_R_exact(x)

    try:
        res = minimize(
            neg_R, h, jac=neg_grad, method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': 300, 'ftol': 1e-15, 'gtol': 1e-12, 'maxls': 50},
        )
        xb = np.maximum(0.0, res.x)
        sb = xb.sum()
        if sb > 0:
            xb /= sb
            rb = R_of(xb)
            if rb > cur_r:
                return xb, rb
    except Exception:
        pass
    return h, cur_r


