import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _dA_dL(L):
    return (2.0 * L
            + np.concatenate(([0.0], L[:-1]))
            + np.concatenate((L[1:], [0.0]))) / 3.0


def grad_R_exact(h, active_tol=1e-6):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = _dA_dL(L)
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    m = L.max()
    active = np.where(L >= m * (1.0 - active_tol))[0]
    dC_dh = np.zeros(N)
    cnt = 0
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx]
            cnt += 1
    if cnt > 0:
        dC_dh /= cnt
    C = m
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def active_set_ascent(h, deadline, max_iter=100000):
    h = np.asarray(h, dtype=float).copy()
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, R_of(h)
    h /= s
    cur_r = R_of(h)
    step = 1e-3
    it = 0
    while time.process_time() < deadline and it < max_iter:
        it += 1
        g = grad_R_exact(h)
        gn = np.linalg.norm(g)
        if gn <= 0:
            break
        d = g / gn
        improved = False
        for _ in range(40):
            hc = np.maximum(h + step * d, 0.0)
            sc = hc.sum()
            if sc <= 0:
                step *= 0.5
                continue
            hc /= sc
            rc = R_of(hc)
            if rc > cur_r:
                h, cur_r = hc, rc
                step *= 1.5
                improved = True
                break
            step *= 0.5
        if not improved and step < 1e-12:
            break
    return h, cur_r


def lbfgsb_polish(h, deadline, maxiter=200):
    h = np.asarray(h, dtype=float).copy()
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, R_of(h)
    h /= s
    cur_r = R_of(h)

    def neg_R(x):
        return -R_of(x)

    def neg_grad(x):
        return -grad_R_exact(x)

    try:
        res = minimize(neg_R, h, jac=neg_grad, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-15, 'gtol': 1e-12})
        hb = np.maximum(0.0, res.x)
        rb = R_of(hb)
        if rb > cur_r:
            return hb, rb
    except Exception:
        pass
    return h, cur_r


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(neg_R_pair, x0, method='Nelder-Mead',
                           bounds=[(0.0, None), (0.0, None)],
                           options={'maxiter': 30, 'xatol': 1e-6, 'fatol': 1e-12})
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def block_sweep(h, deadline, rng, B):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - B + 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = h[i:i + B].copy()

        def neg_R_block(x):
            h[i:i + B] = x
            return -R_of(h)

        try:
            res = minimize(neg_R_block, x0, method='Nelder-Mead',
                           bounds=[(0.0, None)] * B,
                           options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13})
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    return np.interp(np.linspace(0, N - 1, N2), np.arange(N), h)


def downsample_avg(h, N2):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N2 >= N:
        return h.copy()
    pad = (-N) % N2
    if pad:
        h = np.concatenate([h, np.full(pad, h[-1])])
    return h.reshape(-1, N2).mean(axis=0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    N0 = len(best)

    # 4x upsampling: finer grid to reduce discretization error before averaging back.
    N1 = min(50000, 4 * N0)
    if N1 > N0 and N1 <= 50000:
        fine_deadline = t0 + budget_seconds * 0.65
        hf = upsample(best, N1)
        rf = R_of(hf)
        print(f"upsample to {N1}: R={rf:.9f}")
        hf, rf = pair_sweep(hf, fine_deadline, rng)
        print(f"  fine pair: R={rf:.9f}")
        if time.process_time() < fine_deadline:
            hf, rf = block_sweep(hf, fine_deadline, rng, 3)
            print(f"  fine block B=3: R={rf:.9f}")
        if time.process_time() < fine_deadline:
            hf, rf = block_sweep(hf, fine_deadline, rng, 3)
            print(f"  fine block B=3 (2): R={rf:.9f}")

        hd = downsample_avg(hf, N0)
        rd = R_of(hd)
        print(f"downsample to {N0}: R={rd:.9f}")
        if rd > best_r:
            best, best_r = hd, rd
            print(f"downsample: new best R={best_r:.9f}")

    # L-BFGS-B exact-gradient polish at N0
    if time.process_time() < hard_deadline:
        h, r = lbfgsb_polish(best.copy(), hard_deadline)
        if r > best_r + 1e-14:
            best, best_r = h, r
            print(f"L-BFGS-B polish: R={best_r:.9f}")

    # One block_sweep B=3 at N0
    if time.process_time() < hard_deadline:
        h, r = block_sweep(best.copy(), hard_deadline, rng, 3)
        if r > best_r + 1e-14:
            best, best_r = h, r
            print(f"block sweep B=3: R={best_r:.9f}")

    print("final R =", best_r, "N =", len(best))
    return best

