    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def grad_R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    active = np.where(L >= C * (1.0 - 1e-9))[0]
    dC_dh = np.zeros(N)
    cnt = 0
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx]
            cnt += 1
    if cnt > 0:
        dC_dh /= cnt
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs(h, deadline, maxiter=3000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h, R_of(h)
    try:
        res = minimize(
            fun=lambda x: -R_of(x),
            jac=lambda x: -grad_R(x),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        cand = np.maximum(0.0, res.x)
        r = R_of(cand)
        if r > R_of(h):
            return cand, r
    except Exception:
        pass
    return h, R_of(h)


def refine_grad(h, deadline, rng=None, tries=30):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    scale = h.max() if h.max() > 0 else 1.0
    lr = 0.1 * scale / max(1.0, np.linalg.norm(h) + 1e-9)
    for t in range(tries):
        if time.process_time() >= deadline:
            break
        g = grad_R(h)
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr * g / gn
        improved = False
        for alpha in (1.0, 0.5, 0.25, 0.1):
            cand = np.maximum(0.0, h + alpha * step)
            r = R_of(cand)
            if r > cur_r:
                h = cand
                cur_r = r
                improved = True
                lr *= 1.2
                break
        if not improved:
            lr *= 0.5
            if lr < 1e-10 * scale:
                break
    return h, cur_r


def coord_sweep(h, deadline, rng=None):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in (0.0, 0.5, 0.8, 0.9, 1.1, 1.25, 1.6, 2.0):
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        for add in (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5):
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def coord_descent(h, deadline, sweeps=3, rng=None):
    h = np.asarray(h, dtype=float).copy()
    best_r = R_of(h)
    for _ in range(sweeps):
        if time.process_time() >= deadline:
            break
        h, r = coord_sweep(h, deadline, rng)
        if r > best_r:
            best_r = r
    return h, best_r


def pair_sweep(h, deadline, rng, maxiter=25):
    """Optimize pairs of adjacent heights with Nelder-Mead (local)."""
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(neg_R_pair, x0, method='Nelder-Mead',
                           bounds=[(0.0, None), (0.0, None)],
                           options={'maxiter': maxiter, 'xatol': 1e-7, 'fatol': 1e-13})
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def active_set_ascent(h, deadline, max_iter=100000):
    h = np.asarray(h, dtype=float).copy()
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return h, R_of(h)
    h /= s
    cur_r = R_of(h)
    step = 1e-3
    it = 0
    while time.process_time() < deadline and it < max_iter:
        it += 1
        g = grad_R(h)
        gn = np.linalg.norm(g)
        if gn <= 0:
            break
        d = g / gn
        improved = False
        for _ in range(40):
            hc = np.maximum(h + step * d, 0.0)
            sc = hc.sum()
            if sc <= 0:
                step *= 0.5
                continue
            hc /= sc
            rc = R_of(hc)
            if rc > cur_r:
                h, cur_r = hc, rc
                step *= 1.5
                improved = True
                break
            step *= 0.5
        if not improved and step < 1e-12:
            break
    return h, cur_r


def downsample_avg(h, N2):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N2 >= N:
        return h.copy()
    pad = (-N) % N2
    if pad:
        h = np.concatenate([h, np.full(pad, h[-1])])
    return h.reshape(-1, N2).mean(axis=0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    N0 = len(best)

    # Try a finer resolution: upsample, polish with pair+small block sweeps,
    # then downsample back by averaging and re-polish at N0.
    N1 = min(50000, 2 * N0)
    if N1 > N0 and N1 <= 50000:
        fine_deadline = t0 + budget_seconds * 0.55
        hf = resample(best, N1)
        rf = R_of(hf)
        print(f"upsample to {N1}: R={rf:.9f}")
        hf, rf = pair_sweep(hf, fine_deadline, rng)
        print(f"  fine pair: R={rf:.9f}")
        if time.process_time() < fine_deadline:
            hf, rf = active_set_ascent(hf, fine_deadline)
            print(f"  fine ascent: R={rf:.9f}")
        if time.process_time() < fine_deadline:
            hf, rf = pair_sweep(hf, fine_deadline, rng)
            print(f"  fine pair (2): R={rf:.9f}")

        hd = downsample_avg(hf, N0)
        rd = R_of(hd)
        print(f"downsample to {N0}: R={rd:.9f}")
        if rd > best_r:
            best, best_r = hd, rd
            print(f"downsample: new best R={best_r:.9f}")

    # Polish at N0 with active-set ascent and pair sweeps
    if time.process_time() < hard_deadline:
        h, r = active_set_ascent(best.copy(), hard_deadline)
        if r > best_r + 1e-14:
            best, best_r = h, r
            print(f"active-set ascent: R={best_r:.9f}")

    if time.process_time() < hard_deadline:
        h, r = pair_sweep(best.copy(), hard_deadline, rng)
        if r > best_r + 1e-14:
            best, best_r = h, r
            print(f"pair sweep: R={best_r:.9f}")

    # Final L-BFGS polish
    if time.process_time() < hard_deadline:
        h, r = polish_lbfgs(best.copy(), hard_deadline, maxiter=1500)
        if r > best_r + 1e-14:
            best, best_r = h, r
            print(f"final lbfgs: R={best_r:.9f}")

    print("final R =", best_r, "N =", len(best))
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _dA_dL(L):
    return (2.0 * L
            + np.concatenate(([0.0], L[:-1]))
            + np.concatenate((L[1:], [0.0]))) / 3.0


def R_beta_of(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    m = L.max()
    z = beta * (L - m)
    lse = m + np.log(np.sum(np.exp(z))) / beta
    if lse <= 0:
        return -1.0
    return sq / (s * s * lse)


def grad_R_beta(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    L = _knots(h)
    dA_dL = _dA_dL(L)
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    m = L.max()
    z = beta * (L - m)
    ez = np.exp(z)
    sez = ez.sum()
    w = ez / sez
    lse = m + np.log(sez) / beta
    dC_dh = np.zeros(N)
    for kL in range(len(L)):
        wk = w[kL]
        if wk < 1e-12:
            continue
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * wk * h[k - idx]
    C = lse
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs_beta(h, beta, deadline, maxiter=800):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h
    try:
        res = minimize(
            fun=lambda x: -R_beta_of(x, beta),
            jac=lambda x: -grad_R_beta(x, beta),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        return np.maximum(0.0, res.x)
    except Exception:
        return h


def pair_sweep(h, deadline, rng):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < 2:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = np.array([h[i], h[i + 1]], dtype=float)

        def neg_R_pair(x):
            h[i] = x[0]
            h[i + 1] = x[1]
            return -R_of(h)

        try:
            res = minimize(
                neg_R_pair, x0, method='Nelder-Mead',
                bounds=[(0.0, None), (0.0, None)],
                options={'maxiter': 30, 'xatol': 1e-6, 'fatol': 1e-12},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i] = xb[0]
        h[i + 1] = xb[1]
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i] = x0[0]
            h[i + 1] = x0[1]
    return h, cur_r


def block_sweep(h, deadline, rng, B):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if N < B:
        return h, R_of(h)
    cur_r = R_of(h)
    order = np.arange(N - B + 1)
    rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        x0 = h[i:i + B].copy()

        def neg_R_block(x):
            h[i:i + B] = x
            return -R_of(h)

        try:
            res = minimize(
                neg_R_block, x0, method='Nelder-Mead',
                bounds=[(0.0, None)] * B,
                options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-13},
            )
            xb = np.maximum(0.0, res.x)
        except Exception:
            xb = x0
        h[i:i + B] = xb
        r = R_of(h)
        if r > cur_r:
            cur_r = r
        else:
            h[i:i + B] = x0
    return h, cur_r


def upsample(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    return np.interp(np.linspace(0, N - 1, N2), np.arange(N), h)


def downsample_avg(h, N2):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N2 >= N:
        return h.copy()
    pad = (-N) % N2
    if pad:
        h = np.concatenate([h, np.full(pad, h[-1])])
    return h.reshape(-1, N2).mean(axis=0)


def local_refine(h, deadline, rng, rounds=2):
    """Beta-polish + pair sweep, cycling, keeping best."""
    h = np.asarray(h, dtype=float).copy()
    best = h.copy()
    best_r = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        for beta in (2000, 6000, 20000):
            if time.process_time() >= deadline:
                break
            cand = polish_lbfgs_beta(h, beta, deadline, maxiter=400)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
                h = cand
        if time.process_time() >= deadline:
            break
        h, r = pair_sweep(h, deadline, rng)
        if r > best_r:
            best, best_r = h.copy(), r
    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds * 0.88
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base_r = R_of(base)
        print("start R =", base_r, "N =", len(base))
    else:
        base = np.ones(64)
        base_r = R_of(base)

    best = base.copy()
    best_r = base_r
    N0 = len(base)

    # Phase 1: heavy local refinement at current resolution.
    # This is cheap per-unit-improvement and often gives the biggest gains.
    phase1 = t0 + budget_seconds * 0.35
    h, r = local_refine(best, phase1, rng, rounds=3)
    if r > best_r:
        best, best_r = h, r
        print(f"phase1 refine: R={best_r:.9f}")

    # Phase 2: try a finer resolution, polish, downsample back.
    for Nc in (2 * N0, 3 * N0):
        if Nc > 50000 or time.process_time() >= hard:
            continue
        if time.process_time() >= t0 + budget_seconds * 0.75:
            break
        sub = min(hard, time.process_time() + budget_seconds * 0.20)
        hc = upsample(best, Nc)
        rc = R_of(hc)
        print(f"trial Nc={Nc}: upsampled R={rc:.9f}")
        hc, rc = local_refine(hc, sub, rng, rounds=2)
        print(f"  Nc={Nc} refine: R={rc:.9f}")
        # Downsample and re-polish at N0
        if time.process_time() < hard:
            hd = downsample_avg(hc, N0)
            rd = R_of(hd)
            hd, rd = local_refine(hd, min(hard, time.process_time() + budget_seconds * 0.08),
                                  rng, rounds=2)
            print(f"  Nc={Nc} down: R={rd:.9f}")
            if rd > best_r:
                best, best_r = hd, rd
                print(f"  Nc={Nc} new best R={best_r:.9f}")

    # Phase 3: final aggressive polish at N0 with block sweeps.
    if time.process_time() < hard:
        h, r = local_refine(best, hard, rng, rounds=2)
        if r > best_r:
            best, best_r = h, r
            print(f"phase3 refine: R={best_r:.9f}")
    if time.process_time() < hard:
        h, r = block_sweep(best.copy(), hard, rng, 3)
        if r > best_r:
            best, best_r = h, r
            print(f"block B=3: R={best_r:.9f}")
    if time.process_time() < hard:
        h, r = block_sweep(best.copy(), hard, rng, 4)
        if r > best_r:
            best, best_r = h, r
            print(f"block B=4: R={best_r:.9f}")

    print("final R =", best_r, "N =", len(best))
    return best

