        sub = min(hard, time.process_time() + budget_seconds * 0.20)
        hc = upsample(best, Nc)
        rc = R_of(hc)
        print(f"trial Nc={Nc}: upsampled R={rc:.9f}")
        hc, rc = local_refine(hc, sub, rng, rounds=2)
        print(f"  Nc={Nc} refine: R={rc:.9f}")
        if time.process_time() < hard:
            hd = downsample_avg(hc, N0)
            rd = R_of(hd)
            hd, rd = local_refine(hd, min(hard, time.process_time() + budget_seconds * 0.08),
                                  rng, rounds=2)
            print(f"  Nc={Nc} down: R={rd:.9f}")
            if rd > best_r:
                best, best_r = hd, rd
                print(f"  Nc={Nc} new best R={best_r:.9f}")

    # Phase 3: final aggressive polish at N0.
    if time.process_time() < hard:
        h, r = local_refine(best, hard, rng, rounds=2)
        if r > best_r:
            best, best_r = h, r
            print(f"phase3 refine: R={best_r:.9f}")
    if time.process_time() < hard:
        h, r = block_sweep(best.copy(), hard, rng, 3)
        if r > best_r:
            best, best_r = h, r
            print(f"block B=3: R={best_r:.9f}")
    if time.process_time() < hard:
        h, r = block_sweep(best.copy(), hard, rng, 4)
        if r > best_r:
            best, best_r = h, r
            print(f"block B=4: R={best_r:.9f}")

    # Phase 4: extra high-beta polish with tight tolerance to squeeze last bits.
    for beta in (50000, 150000):
        if time.process_time() >= hard:
            break
        cand = polish_lbfgs_beta(best, beta, hard, maxiter=600)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print(f"hi-beta {beta}: R={best_r:.9f}")

    print("final R =", best_r, "N =", len(best))
    return best
